/**
 * Writes packages/<name>/src/package-version.ts from that package's package.json.
 * Releases must rerun `npx nx run-many -t prepare -p react angular` after
 * `nx release version` bumps package.json, then commit the regenerated files.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';

const workspaceRoot = resolve(import.meta.dirname, '../../..');

const PACKAGES = new Set(['react', 'angular']);

/** Renders the generated `package-version.ts` source for a version string. */
export const packageVersionSource = (version) =>
  [
    '// Generated by tools/growth/install/write-package-version.mjs from package.json. Do not edit.',
    '// prettier-ignore',
    `export const PACKAGE_VERSION = ${JSON.stringify(version)};`,
    '',
  ].join('\n');

/**
 * Writes `packages/<name>/src/package-version.ts` when its content differs from
 * the version in `packages/<name>/package.json`. Returns true when it wrote.
 */
export function writePackageVersion(name, root = workspaceRoot) {
  if (!PACKAGES.has(name)) {
    throw new Error(
      `write-package-version: "${name}" is not one of ${[...PACKAGES].join(', ')}`,
    );
  }
  const packageRoot = join(root, 'packages', name);
  const { version } = JSON.parse(
    readFileSync(join(packageRoot, 'package.json'), 'utf8'),
  );
  const target = join(packageRoot, 'src', 'package-version.ts');
  const contents = packageVersionSource(version);
  let existing;
  try {
    existing = readFileSync(target, 'utf8');
  } catch {
    existing = undefined;
  }
  if (existing === contents) return false;
  writeFileSync(target, contents);
  return true;
}

if (process.argv[1] === import.meta.filename) {
  try {
    writePackageVersion(process.argv[2]);
  } catch (error) {
    console.error(error instanceof Error ? error.message : error);
    process.exit(1);
  }
}
